package io.tuji.app;
import org.junit.Test;import static org.junit.Assert.*;import androidx.test.platform.app.InstrumentationRegistry;import android.content.*;import java.util.*;
public class BundleNamesTest{@Test public void namesPersistAndRespectMinuteAndTimezone()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();TimeZone old=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("Asia/Hong_Kong"));Calendar cal=Calendar.getInstance();cal.clear();cal.set(2088,11,12,5,31);long t=cal.getTimeInMillis();SharedPreferences p=c.getSharedPreferences("bundle_names",0);p.edit().remove("208812120531").remove("208812120532").commit();assertEquals("208812120531.tuji.zip",BundleNames.allocate(c,t));assertEquals("208812120531_2.tuji.zip",BundleNames.allocate(c,t));assertEquals(2,c.getSharedPreferences("bundle_names",0).getInt("208812120531",0));assertEquals("208812120532.tuji.zip",BundleNames.allocate(c,t+60000));assertEquals("208812120531_3.tuji.zip",BundleNames.allocate(c,t));p.edit().remove("208812120531").remove("208812120532").commit();}finally{TimeZone.setDefault(old);}}}
